CREATE OR REPLACE TABLE `PROJECT_ID.abr_00_config.scale_sentinel` AS
-- Outside the ordered scale. Excluded from every box, the mean, and the
-- scale length. These sit at different codes in different questions and
-- sometimes mid-scale, so they can only be identified by label.
SELECT * FROM UNNEST([
  'don\'t know',
  'dont know',
  'do not know',
  'not sure',
  'i\'m not sure',
  'im not sure',
  'prefer not to say',
  'prefer not to answer',
  'none of the above',
  'other',
  'something else',
  'n/a',
  'not applicable',
  'does not apply',
  'no opinion',
  'i don\'t remember',
  'dont remember',
  'i did not like any of these',
  'no answer'
]) AS phrase;

CREATE OR REPLACE TABLE `PROJECT_ID.abr_00_config.construct_polarity` AS
-- A question about something undesirable inverts favourability.
SELECT * FROM UNNEST([STRUCT<pattern STRING, polarity STRING>
  ('boring', 'negative'),
  ('confusing', 'negative'),
  ('scary', 'negative'),
  ('upsetting', 'negative'),
  ('too long', 'negative'),
  ('showed too much', 'negative'),
  ('reduced your interest', 'negative'),
  ('reduced interest', 'negative'),
  ('keep you from', 'negative'),
  ('concerns', 'negative'),
  ('disappointing', 'negative'),
  ('annoying', 'negative'),
  ('hard to understand', 'negative'),
  ('too much of the story', 'negative'),
  ('too little, the right amount, or too much', 'mid_optimal')
]);

