-- "Mentioned anywhere across 20 open ends" is ~100% for every theme.
SELECT * FROM UNNEST([STRUCT<role STRING, meta STRING>
  ('first_reaction', 'KPOSTINT'),
  ('first_reaction', 'POSTREACT'),
  ('likes', 'KPFAVE'),
  ('likes', 'KPLM'),
  ('likes', 'TRINTERST'),
  ('likes', 'POSTAPPEAL'),
  ('dislikes', 'KPNL'),
  ('dislikes', 'TRREDUC'),
  ('dislikes', 'DNOGO'),
  ('dislikes', 'CCCONC'),
  ('scary_probe', 'KPSCAR3'),
  ('comprehension', 'KABOUT'),
  ('comprehension', 'KPHAPPEN'),
  ('comprehension', 'POSTUNDERST'),
  ('comprehension', 'RECALL'),
  ('unaided_recall', 'KPTOMM'),
  ('unaided_recall', 'RECALL'),
  ('unaided_recall', 'RETITLE'),
  ('unaided_recall', 'DRELEASE'),
  ('intent_prose', 'DTHEAT'),
  ('intent_prose', 'DSTREAM'),
  ('intent_prose', 'PRECO'),
  ('intent_prose', 'NPRECO'),
  ('intent_prose', 'ECHREQ'),
