CREATE OR REPLACE TABLE `PROJECT_ID.abr_00_config.prose_cue` AS
-- The most extreme cue in a sentence wins; a negation just before it flips
-- the score. Coverage and confidence are reported, never assumed.
SELECT * FROM UNNEST([STRUCT<family STRING, pattern STRING, score INT64>
  ('appeal', 'extremely appealing|incredibly appealing|hugely appealing|couldn\'t be more appealing', 5),
  ('appeal', 'very appealing|highly appealing|really appealing|so appealing|deeply appealing', 5),
  ('appeal', 'absolutely|instant(ly)? appealing|exactly (what|the kind)|right up my', 5),
  ('appeal', 'quite appealing|pretty appealing|fairly appealing|appealing enough|appeals to me', 4),
  ('appeal', '\\bappealing\\b|\\bappeals\\b|looks good|looks fun|looks charming|looks sweet', 4),
  ('appeal', 'moderately appealing|somewhat appealing|mildly appealing|a little appealing', 3),
  ('appeal', 'on the fence|depends|neither|indifferent|take it or leave it|middling', 3),
  ('appeal', 'not (very|especially|particularly) appealing|limited appeal|little appeal', 2),
  ('appeal', 'not appealing|no appeal|unappealing|does ?n[o\']?t appeal', 1),
  ('appeal', 'not at all appealing|zero appeal|actively off-?putting', 1),
  ('appeal', 'would love it|will (definitely|surely) (love|be drawn)|right up (their|my|his|her) alley|built for (them|him|her)|eat (this|it) up', 5),
  ('appeal', 'they\'?d probably love|would be into it|should enjoy', 4),
  ('appeal', 'might be (a bit much|too much)|bit much for', 2),
  ('likelihood', '100% (buying|going)|buying tickets|already bought|thursday previews|opening (weekend|night)|first (weekend|day)', 5),
  ('likelihood', 'extremely likely|certain(ly)?|without (a )?doubt|without hesitation|guaranteed|absolutely|for sure|no question', 5),
  ('likelihood', 'very likely|highly likely|highly recommend|definitely (would|recommend|going)|will definitely|would definitely', 5),
  ('likelihood', 'can\'?t wait|beg(ging)? me|would love|right up (their|my|his|her) alley|eat (this|it) up|built for (them|him|her)', 5),
  ('likelihood', 'likely|probably would|would probably|i would|we would|pretty likely|quite likely|expect (to|we)|planning to', 4),
  ('likelihood', 'somewhat likely|fairly likely|good chance|open to it|might well|would be into', 4),
  ('likelihood', 'maybe|possibly|could go either way|if (the|it|there)|depends on|not sure|50/50|toss-?up|on the fence', 3),
  ('likelihood', 'wait (for|until) (it|streaming|home|rental|the)|rather wait|prefer to wait|when it hits|a bit much', 2),
  ('likelihood', 'not (very|especially|particularly) likely|unlikely|probably not|doubt (i|we)|would rather spend', 2),
  ('likelihood', 'zero (chance|likelihood)|refuse to|not likely|would ?n[o\']?t|no chance|never|not at all likely|definitely not', 1),
  ('interest', 'extremely interested|obsessed|huge fan|massive fan|passionate about', 5),
  ('interest', 'very interested|highly interested|really interested|big fan|love (them|these|those)', 5),
  ('interest', 'interested|keen|enjoy(s)? (them|these)|we like|fan of', 4),
  ('interest', 'somewhat interested|moderately interested|mildly interested|occasionally|now and then', 3),
  ('interest', 'neutral|indifferent|no strong (feeling|view)|take or leave', 3),
  ('interest', 'not (very|especially|particularly) interested|limited interest|rarely', 2),
  ('interest', 'not interested|no interest|never watch|avoid', 1),
  ('interest', 'we love|gets played in (my|our) house|anything with', 5),
  ('interest', 'pretty casual|casual interest|moderate interest|shoot(ing)? hoops|now and then|appreciate the', 3),
  ('interest', 'do ?n[o\']?t watch a ton|are ?n[o\']?t a (huge|big)|more into|not (a )?huge', 2),
  ('comfort', 'completely comfortable|entirely comfortable|no concerns at all|perfectly fine', 5),
  ('comfort', 'very comfortable|comfortable', 4),
  ('comfort', 'mostly comfortable|comfortable with (some|a few)|minor concerns|with reservations', 3),
  ('comfort', 'somewhat uncomfortable|hesitant|would preview (it|first)|concerned', 2),
  ('comfort', 'very uncomfortable|not comfortable|would ?n[o\']?t allow|absolutely not', 1)
]);

CREATE OR REPLACE TABLE `PROJECT_ID.abr_00_config.prose_negation` AS
SELECT * FROM UNNEST([
  'not',
  'no',
  'never',
  'hardly',
  'barely',
  'wouldn\'t',
  'would not',
  'don\'t',
  'do not',
  'isn\'t',
  'is not',
  'doubt',
  'unlikely'
]) AS token;

CREATE OR REPLACE TABLE `PROJECT_ID.abr_00_config.prose_not_applicable` AS
-- A persona writing "N/A - I am a parent" is correcting a base the harness
-- got wrong, not failing to answer. Counted separately from unscored.
SELECT '^\\s*(n/?a\\b|not applicable|does not apply|i\'?m not a parent|i am not a parent|no children)' AS pattern;

